import{_ as l,o as e,a as d,b as a}from"./app.C41L12d5.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"附录","link":"/api/appendix/appendix"},{"text":"Reg矢量计算接口软仿情况汇总","link":"/api/appendix/reg_vector_compute_interface_soft_simulation_summary"}]},"headers":[],"relativePath":"api/appendix/reg_vector_compute_interface_soft_simulation_summary.md","filePath":"api/appendix/reg_vector_compute_interface_soft_simulation_summary.md","lastUpdated":1787050286000}'),n={name:"api/appendix/reg_vector_compute_interface_soft_simulation_summary.md"};function i(r,t,g,f,o,_){return e(),d("div",null,[...t[0]||(t[0]=[a('<div><article class="markdown-body"><h1>Reg矢量计算接口软仿情况汇总</h1><p>本节汇总介绍了Reg矢量计算接口软仿数据类型的情况，本节内容仅针对如下型号生效：</p><p>Ascend 950PR/Ascend 950DT</p><p><a href="../SIMD-API/basic_api/reg_vector_compute/reg_data_load/reg_data_load.html">Reg数据搬入</a>和<a href="../SIMD-API/basic_api/reg_vector_compute/reg_data_store/reg_data_store.html">Reg数据搬出</a>目录下提供了Unified Buffer（UB）与RegTensor、UB与MaskReg之间的数据搬运接口。</p><p>UB与RegTensor之间的数据搬运根据操作数的数据类型位宽来搬运，与数据类型本身无关，表1和表2列出的软仿支持的数据类型包括以下情况：</p><ul><li>底层硬件不支持该数据类型，通过其他位宽相同的数据类型支持的搬运指令实现。</li><li>底层硬件不支持该数据类型，通过多种接口组合软仿实现。</li><li>底层硬件不支持该数据类型，通过双搬入/双搬出模式软仿实现RegTraitNumTwo的数据类型。</li></ul><p><strong>表1</strong> Reg数据搬入</p><table><thead><tr><th align="left">接口</th><th align="left">软仿支持数据类型</th></tr></thead><tbody><tr><td align="left">连续对齐搬入（LoadAlign）</td><td align="left">bool、complex32、int64_t、uint64_t、complex64</td></tr><tr><td align="left">非连续对齐搬入（LoadAlign）</td><td align="left">bool、complex32</td></tr><tr><td align="left">连续非对齐搬入（LoadUnAlign）</td><td align="left">bool、complex32、int64_t、uint64_t、complex64</td></tr><tr><td align="left">MaskReg搬入（LoadAlign）</td><td align="left">-</td></tr><tr><td align="left">MaskReg搬入（MaskGenWithRegTensor）</td><td align="left">-</td></tr><tr><td align="left">离散搬入（Gather）</td><td align="left">int64_t、uint64_t</td></tr><tr><td align="left">离散搬入（GatherB）</td><td align="left">-</td></tr><tr><td align="left">Load</td><td align="left">bool、complex32、int64_t、uint64_t、complex64</td></tr><tr><td align="left">Move</td><td align="left">bool、int64_t、uint64_t、complex64</td></tr></tbody></table><p><strong>表2</strong> Reg数据搬出</p><table><thead><tr><th align="left">接口</th><th align="left">软仿支持数据类型</th></tr></thead><tbody><tr><td align="left">连续对齐搬出（StoreAlign）</td><td align="left">bool、complex32、int64_t、uint64_t、complex64</td></tr><tr><td align="left">非连续对齐搬出（StoreAlign）</td><td align="left">bool、complex32</td></tr><tr><td align="left">连续非对齐搬出（StoreUnAlign）</td><td align="left">bool、complex32、int64_t、uint64_t、complex64</td></tr><tr><td align="left">MaskReg搬出（StoreAlign）</td><td align="left">-</td></tr><tr><td align="left">MaskReg非对齐搬出（StoreUnAlign）</td><td align="left">-</td></tr><tr><td align="left">离散搬出（Scatter）</td><td align="left">int64_t、uint64_t</td></tr><tr><td align="left">Store</td><td align="left">bool、complex32、int64_t、uint64_t、complex64</td></tr></tbody></table><p><strong>表3</strong> 基础算术</p><table><thead><tr><th align="left">接口</th><th align="left">软仿支持数据类型</th></tr></thead><tbody><tr><td align="left">Exp</td><td align="left">half（SubNormal）、float（SubNormal）</td></tr><tr><td align="left">Sqrt</td><td align="left">half（SubNormal）、float（SubNormal）</td></tr><tr><td align="left">Add</td><td align="left">complex32、int64_t、uint64_t、complex64</td></tr><tr><td align="left">AddC</td><td align="left">-</td></tr><tr><td align="left">Sub</td><td align="left">complex32、int64_t、uint64_t、complex64</td></tr><tr><td align="left">SubC</td><td align="left">-</td></tr><tr><td align="left">Adds</td><td align="left">complex32、int64_t、uint64_t、complex64</td></tr><tr><td align="left">Max</td><td align="left">int64_t、uint64_t</td></tr><tr><td align="left">Min</td><td align="left">int64_t、uint64_t</td></tr><tr><td align="left">Maxs</td><td align="left">int64_t、uint64_t</td></tr><tr><td align="left">Mins</td><td align="left">int64_t、uint64_t</td></tr><tr><td align="left">Div</td><td align="left">int16_t、uint16_t、half（SubNormal）、int32_t、uint32_t、float（SubNormal）、complex32、int64_t、uint64_t、complex64</td></tr><tr><td align="left">Neg</td><td align="left">int64_t</td></tr><tr><td align="left">Ln</td><td align="left">half（SubNormal）、float（SubNormal）</td></tr><tr><td align="left">Log</td><td align="left">half（SubNormal）、float（SubNormal）</td></tr><tr><td align="left">Log2</td><td align="left">half、float</td></tr><tr><td align="left">Log10</td><td align="left">half、float</td></tr><tr><td align="left">Mul</td><td align="left">complex32、int64_t、uint64_t、complex64</td></tr><tr><td align="left">Mull</td><td align="left">-</td></tr><tr><td align="left">Muls</td><td align="left">complex32、int64_t、uint64_t、complex64</td></tr><tr><td align="left">Abs</td><td align="left">complex32、int64_t、complex64</td></tr><tr><td align="left">Relu</td><td align="left">int64_t</td></tr><tr><td align="left">Prelu</td><td align="left">-</td></tr><tr><td align="left">LeakyRelu</td><td align="left">-</td></tr></tbody></table><p><strong>表4</strong> 逻辑计算</p><table><thead><tr><th align="left">接口</th><th align="left">软仿支持数据类型</th></tr></thead><tbody><tr><td align="left">Not</td><td align="left">int64_t、uint64_t</td></tr><tr><td align="left">And</td><td align="left">int64_t、uint64_t</td></tr><tr><td align="left">Or</td><td align="left">int64_t、uint64_t</td></tr><tr><td align="left">Xor</td><td align="left">int64_t、uint64_t</td></tr><tr><td align="left">ShiftLeft</td><td align="left">int64_t、uint64_t</td></tr><tr><td align="left">ShiftRight</td><td align="left">int64_t、uint64_t</td></tr><tr><td align="left">ShiftLefts</td><td align="left">int64_t、uint64_t</td></tr><tr><td align="left">ShiftRights</td><td align="left">int64_t、uint64_t</td></tr></tbody></table><p><strong>表5</strong> 复合计算</p><table><thead><tr><th align="left">接口</th><th align="left">软仿支持数据类型</th></tr></thead><tbody><tr><td align="left">AbsSub</td><td align="left">int64_t</td></tr><tr><td align="left">ExpSub</td><td align="left">-</td></tr><tr><td align="left">Axpy</td><td align="left">int64_t、uint64_t</td></tr><tr><td align="left">MulDstAdd</td><td align="left">-</td></tr><tr><td align="left">MulAddDst</td><td align="left">int64_t、uint64_t</td></tr><tr><td align="left">MulsCast</td><td align="left">-</td></tr></tbody></table><p><strong>表6</strong> 比较与选择</p><table><thead><tr><th align="left">接口</th><th align="left">软仿支持数据类型</th></tr></thead><tbody><tr><td align="left">Compare</td><td align="left">-</td></tr><tr><td align="left">Compares</td><td align="left">-</td></tr><tr><td align="left">Select</td><td align="left">bool、int64_t、uint64_t</td></tr><tr><td align="left">Squeeze</td><td align="left">-</td></tr></tbody></table><p><strong>表7</strong> 类型转换</p><table><thead><tr><th align="left">接口</th><th align="left">软仿支持数据类型</th></tr></thead><tbody><tr><td align="left">Cast</td><td align="left">e8m02bf16、bf162e8m0</td></tr><tr><td align="left">Truncate</td><td align="left">-</td></tr></tbody></table><p><strong>表8</strong> 归约计算</p><table><thead><tr><th align="left">接口</th><th align="left">软仿支持数据类型</th></tr></thead><tbody><tr><td align="left">Reduce</td><td align="left">int64_t、uint64_t</td></tr><tr><td align="left">ReduceDataBlock</td><td align="left">-</td></tr><tr><td align="left">PairReduceElem</td><td align="left">-</td></tr></tbody></table><p><strong>表9</strong> 数据填充</p><table><thead><tr><th align="left">接口</th><th align="left">软仿支持数据类型</th></tr></thead><tbody><tr><td align="left">Duplicate</td><td align="left">bool、fp4x2_e2m1_t、fp4x2_e1m2_t、hifloat8_t、fp8_e8m0_t、fp8_e5m2_t、fp8_e4m3fn_t、complex32、int64_t、uint64_t、complex64</td></tr></tbody></table><p><strong>表10</strong> 离散操作</p><table><thead><tr><th align="left">接口</th><th align="left">软仿支持数据类型</th></tr></thead><tbody><tr><td align="left">Gather</td><td align="left">-</td></tr></tbody></table><p><strong>表11</strong> 数据重排</p><table><thead><tr><th align="left">接口</th><th align="left">软仿支持数据类型</th></tr></thead><tbody><tr><td align="left">Interleave</td><td align="left">int64_t、uint64_t</td></tr><tr><td align="left">DeInterleave</td><td align="left">int64_t、uint64_t</td></tr></tbody></table><p><strong>表12</strong> 数据压缩</p><table><thead><tr><th align="left">接口</th><th align="left">软仿支持数据类型</th></tr></thead><tbody><tr><td align="left">Unsqueeze</td><td align="left">-</td></tr><tr><td align="left">Pack</td><td align="left">-</td></tr><tr><td align="left">UnPack</td><td align="left">-</td></tr></tbody></table><p><strong>表13</strong> 直方图计算</p><table><thead><tr><th align="left">接口</th><th align="left">软仿支持数据类型</th></tr></thead><tbody><tr><td align="left">Histograms</td><td align="left">-</td></tr></tbody></table><p><strong>表14</strong> 索引操作</p><table><thead><tr><th align="left">接口</th><th align="left">软仿支持数据类型</th></tr></thead><tbody><tr><td align="left">Arange</td><td align="left">int64_t</td></tr></tbody></table><p><strong>表15</strong> 同步控制</p><table><thead><tr><th align="left">接口</th><th align="left">软仿支持数据类型</th></tr></thead><tbody><tr><td align="left">LocalMemBar</td><td align="left">-</td></tr></tbody></table><p><strong>表16</strong> 系统变量访问</p><table><thead><tr><th align="left">接口</th><th align="left">软仿支持数据类型</th></tr></thead><tbody><tr><td align="left">ClearSpr</td><td align="left">-</td></tr><tr><td align="left">GetSpr</td><td align="left">-</td></tr></tbody></table></article></div>',1)])])}const s=l(n,[["render",i]]);export{h as __pageData,s as default};
